using Contoso.Services;

namespace Contoso.Services.Tests;

[TestClass]
public sealed class ServiceRegistryTests
{
    private readonly ServiceRegistry _registry = new();

    public interface IGreeter { }
    private sealed class Greeter : IGreeter { }

    [TestMethod]
    public void Resolve_AfterRegister_ReturnsSameInstance()
    {
        var greeter = new Greeter();
        _registry.Register<IGreeter>(greeter);

        var resolved = _registry.Resolve<IGreeter>();

        Assert.AreSame(greeter, resolved);
    }

    [TestMethod]
    public void Resolve_Unregistered_ReturnsNull()
    {
        var resolved = _registry.Resolve<IGreeter>();

        Assert.IsNull(resolved);
    }

    [TestMethod]
    public void GetAll_ContainsRegisteredService_AndNotAfterRemoval()
    {
        var greeter = new Greeter();
        _registry.Register<IGreeter>(greeter);

        CollectionAssert.Contains(_registry.GetAll().ToList(), greeter);

        _registry.Remove<IGreeter>();

        CollectionAssert.DoesNotContain(_registry.GetAll().ToList(), greeter);
    }

    [TestMethod]
    public void GetAll_EmptyBeforeRegistration_NotEmptyAfter()
    {
        Assert.AreEqual(0, _registry.GetAll().Count);

        _registry.Register<IGreeter>(new Greeter());

        Assert.AreNotEqual(0, _registry.GetAll().Count);
    }
}

